sys_script_include.script:
var ExCaseUtils = Class.create();
ExCaseUtils.prototype = {
    initialize: function() {},

    getGroupMembers: function(groupId) {
        var ids = [];
        var gm = new GlideRecord('sys_user_grmember');
        gm.addQuery('group', groupId);
        gm.query();
        while (gm.next()) {
            ids.push(gm.getValue('user'));
        }
        return 'sys_idIN' + ids.join(',');
    },

    type: 'ExCaseUtils'
};
